package com.mantou.salesdialer.contacts;
import java.util.*;
public final class PhoneIntakeCheck {
 static int checks;static void eq(Object a,Object b){checks++;if(!Objects.equals(a,b))throw new AssertionError("PHONE_ASSERTION_"+checks);}static void fail(Runnable r,String msg){checks++;try{r.run();}catch(Exception e){if(msg.equals(e.getMessage()))return;throw new AssertionError(e.getMessage());}throw new AssertionError("EXPECTED_"+msg);}
 public static void main(String[] args){String n="199"+"0".repeat(7)+"1";var parsed=PhoneIntakeModel.parse(" "+n+" ");eq(parsed.status,"VALID");eq(parsed.canonical,n);eq(PhoneIntakeModel.mask(n),"199****0001");eq(PhoneIntakeModel.parse("\u00a0\ufeff"+n+"\u3000").canonical,n);System.out.println("T656 mainland mobile format and host-compatible edge whitespace passed");
 for(String v:List.of("+86"+n,"010-"+"5".repeat(8),n+"#123","("+n+")"))eq(PhoneIntakeModel.parse(v).status,"UNSUPPORTED");for(String v:List.of("SIM-001","DEMO-001","<script>","123","",n+"X"))eq(PhoneIntakeModel.parse(v).status,"INVALID");eq(PhoneIntakeModel.parse(null).status,"INVALID");eq(PhoneIntakeModel.parse(" ".repeat(129)).status,"INVALID");System.out.println("T657 unsupported country/landline/extension and invalid sources never normalize passed");
 eq(PhoneIntakeModel.rows(n+"\r\n").size(),2);eq(PhoneIntakeModel.rows(n+"\r\n").get(1),"");PhoneIntakeModel.validate(Collections.nCopies(200,n),"SOURCE",PhoneIntakeModel.Qualification.CONFIRMED);checks++;fail(()->PhoneIntakeModel.validate(Collections.nCopies(201,n),"S",PhoneIntakeModel.Qualification.UNKNOWN),"INVALID_BATCH");fail(()->PhoneIntakeModel.validate(List.of(n),"\u00a0",PhoneIntakeModel.Qualification.UNKNOWN),"INVALID_BATCH");fail(()->PhoneIntakeModel.validate(List.of("a".repeat(129)),"S",PhoneIntakeModel.Qualification.UNKNOWN),"INVALID_BATCH");System.out.println("T658 batch limits and explicit qualification/source structural contract passed");
 eq(PhoneIntakeModel.submissionBoundary(PhoneIntakeModel.DataClass.FORMAT_FIXTURE),"FORMAT_FIXTURE_ONLY");eq(PhoneIntakeModel.submissionBoundary(PhoneIntakeModel.DataClass.LOCAL_PHONE_INTAKE),"PRODUCTION_IDENTITY_UNVERIFIED");System.out.println("T659 fixture and local intake never become phone authorization passed");
 System.out.println("PASS: "+checks+" assertions; 4 phone-intake scenarios; generated format fixtures, zero telephone");}
}
